"""Proof SVG assets with Chromium; build the review guide and motion scene."""
from pathlib import Path
import base64, json, subprocess, html
from PIL import Image, ImageOps, ImageDraw

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'output' / 'identity'
NODE = Path(r'C:\Users\mahro\.cache\codex-runtimes\codex-primary-runtime\dependencies\node\bin\node.exe')
PLAYWRIGHT = NODE.parent.parent / 'node_modules' / 'playwright'
CHROME = Path(r'C:\Program Files\Google\Chrome\Application\chrome.exe')

def documents():
    font = base64.b64encode((ROOT/'assets/fonts/Cairo.ttf').read_bytes()).decode()
    fontcss = f"@font-face{{font-family:Cairo;src:url(data:font/ttf;base64,{font}) format('truetype');font-weight:200 1000;font-display:block}}"
    logo = (OUT/'logo-primary.svg').read_text(encoding='utf-8')
    logo = logo[logo.index('<svg'):]
    colors = [('أخضر الهوية','#006838'),('أخضر عميق','#073E2A'),('أخضر التأكيد','#B5F36B'),('أبيض دافئ','#F7F8EF'),('حبر','#11261B')]
    swatches = ''.join(f'<div><span style="background:{v}"></span><b>{n}</b><code>{v}</code></div>' for n,v in colors)
    cards = ''.join(f'<figure><img src="{i}.png"><figcaption>{t} <a href="{i}.svg">SVG</a> · <a href="{i}.png">PNG</a></figcaption></figure>' for i,t in [('01-introduction','01 — التعريف'),('02-quote','02 — التصريحات'),('03-comparison','03 — المقارنة'),('04-important-news','04 — الخبر'),('05-voting','05 — التصويت'),('06-story','06 — القصة')])
    guide = '''<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><title>أولتراس الموحدة — دليل الهوية</title><style>FONT
*{box-sizing:border-box}body{margin:0;background:#F7F8EF;color:#073E2A;font-family:Cairo,Arial,sans-serif}main{max-width:1240px;margin:auto}section{padding:75px 70px;border-bottom:1px solid #D7E2D6}.eyebrow{font-size:15px;font-weight:700;letter-spacing:.06em}.cover{background:#006838;color:#F7F8EF;padding-bottom:40px}.cover .top{display:flex;justify-content:space-between}.cover h1{font-size:86px;line-height:1.35;margin:40px 0 15px;font-weight:950}.cover h1 span{color:#B5F36B}.cover p{font-size:25px;margin:0}.cover .logo{background:#F7F8EF;border-radius:50% 50% 30% 30%;width:430px;height:375px;margin:35px auto 5px;overflow:hidden}.cover .logo svg{width:100%;height:100%}h2{font-size:47px;line-height:1.3;margin:0 0 30px}h3{font-size:26px}p,li{font-size:20px;line-height:1.95}a{color:inherit;text-underline-offset:5px}code{direction:ltr;display:inline-block}.swatches{display:grid;grid-template-columns:repeat(5,1fr);gap:16px}.swatches span{height:150px;display:block;border-radius:60px 60px 12px 12px;border:1px solid #D7E2D6;margin-bottom:14px}.swatches b,.swatches code{display:block}.types{display:grid;grid-template-columns:1fr 1fr;gap:35px;align-items:center}.type-big{font-size:110px;font-weight:950;line-height:1.7}.outline{color:#F7F8EF;paint-order:stroke fill;-webkit-text-stroke:5.5px #006838}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:36px}figure{margin:0}figure img{width:100%;display:block;border:1px solid #D7E2D6}figcaption{font-size:16px;margin-top:12px}.rules{display:grid;grid-template-columns:repeat(3,1fr);gap:30px}.num{font-size:48px;font-weight:900;color:#006838}.sources p{font-size:16px;overflow-wrap:anywhere}.motion{display:inline-block;padding:13px 26px;background:#006838;color:#F7F8EF;border-radius:28px;text-decoration:none}.note{font-size:16px;color:#5C7467}.downloads{display:flex;gap:20px;flex-wrap:wrap}footer{padding:35px 70px;background:#073E2A;color:#F7F8EF}@media(max-width:760px){section{padding:35px 25px}.cover h1{font-size:54px}.cover .logo{width:300px;height:270px}.swatches{grid-template-columns:repeat(3,1fr)}.grid,.types,.rules{grid-template-columns:1fr}.type-big{font-size:80px}}@page{size:A4;margin:12mm}@media print{main{max-width:none}section{padding:30px 16px;break-before:page;border:none}.cover{break-before:auto;min-height:265mm}.cover .logo{margin-top:80px}.cover h1{font-size:69px}.grid,.types{grid-template-columns:repeat(2,1fr)}.rules{grid-template-columns:repeat(3,1fr)}.swatches{grid-template-columns:repeat(5,1fr)}.grid{gap:10px}.grid figure{break-inside:avoid}.grid figure img{max-height:61mm;width:auto;max-width:100%;margin:auto}p,li{font-size:14px;line-height:1.6}h2{font-size:33px;margin-bottom:18px}h3{font-size:20px}.num{font-size:36px}figcaption{font-size:11px;margin-top:7px}.note{font-size:12px}.type-big{font-size:80px}.swatches span{height:100px}.rules{gap:15px}a{text-decoration:none}footer{font-size:12px}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
</style><main><section class="cover"><div class="top"><b>أولتراس الموحدة</b><span>هوية بصرية / اتجاه أول — 08.10.2026</span></div><h1>جمهور واحد.<br><span>حضور واضح.</span></h1><p>هوية لمجموعة مناصرين مستقلة</p><div class="logo">LOGO</div><p class="note" style="color:#F7F8EF">نظام قابل للتحرير: شعار، منشورات، قصة وحركة.</p></section>
<section><div class="eyebrow">01 / الفكرة والشعار</div><h2>من الجمهور إلى علامة.</h2><p>خمس شخصيات بأشكال دائرية ترفع علماً متموجاً. الخطوط اللينة والإيقاع الصاعد ينقلان طاقة الجمهور داخل رمز بسيط. الاسم منفصل عن الرمز ليبقى التعديل والتصدير سهلاً.</p><div class="rules"><div><span class="num">01</span><h3>استقلالية واضحة</h3><p>الاسم هو «أولتراس الموحدة». المجموعة مستقلة وليست هوية رسمية للقائمة.</p></div><div><span class="num">02</span><h3>أقل عناصر</h3><p>جمهور وعلم واسم. لا درع ولا كرة ولا زخارف إضافية تنافس الرمز.</p></div><div><span class="num">03</span><h3>مساحة تنفّس</h3><p>اترك حول الشعار مساحة لا تقل عن قطر الرأس الأوسط. استعمل الرمز وحده عند الأحجام الصغيرة.</p></div></div><div class="downloads"><a href="logo-primary.svg">الشعار الأساسي</a><a href="logo-black.svg">أسود</a><a href="logo-white.svg">أبيض</a><a href="avatar.svg">صورة الحساب</a></div><p class="note">تفصيل شعار القائمة داخل العلم مناسب للأحجام الكبيرة. النسخ الأحادية تحتفظ بالعلم وعلامته الداخلية؛ اختر الرمز وحده عند ضيق المساحة.</p></section>
<section><div class="eyebrow">02 / اللون والحروف</div><h2>أخضر ثابت. إيقاع حيوي.</h2><div class="swatches">SWATCHES</div><p>الأخضر الأساسي هو نقطة البداية، والأبيض الدافئ يعطي مساحة للنص. الأخضر الفاتح يستخدم للتأكيد في خطوط قصيرة ونقاط وعناصر محدودة، ولا يستخدم للنص الصغير فوق الأبيض.</p><div class="types"><div class="type-big">حضور<br><span class="outline">حضور</span></div><div><h3>Cairo Variable</h3><p>عناوين ثقيلة بوزن 850–950، متن 600–700، وتناوب بين الحروف الممتلئة والمفرغة. النص العربي في الملفات طبقة قابلة للتعديل؛ الخط مضمّن داخل SVG ومرفق مع رخصته المفتوحة.</p><p class="note">أبقِ الخط المفرّغ في الكلمات الكبيرة فقط. لا تتمدد الحروف أو تضغطها عرضياً.</p></div></div></section>
<section><div class="eyebrow">03 / النظام التحريري</div><h2>قوالب متعددة، لغة واحدة.</h2><div class="grid">CARDS</div><p class="note">1080×1350 للمنشورات، 1080×1920 للقصة، و1080×1080 لصورة الحساب. النصوص الموضوعة بين الأقواس أو المسماة «هنا» هي حقول تحرير. بطاقة التصريح نموذج أرشيفي مؤرخ؛ بطاقة الخبر ليست خبراً منشوراً.</p></section>
<section><div class="eyebrow">04 / الحركة والتسليم</div><h2>حركة ناعمة لها سبب.</h2><div class="rules"><div><span class="num">0–2s</span><h3>دخول العلامة</h3><p>ظهور تدريجي وصعود قصير للجمهور. تموّج محدود للعلم من نقطة اتصاله.</p></div><div><span class="num">2–5s</span><h3>العنوان</h3><p>ظهور السطور بالتتابع، مع انتقال الكلمة الكبيرة من حدود إلى تعبئة كاملة.</p></div><div><span class="num">5–8s</span><h3>التعريف والخروج</h3><p>شريط اسم المتحدث وصفته، ثم خروج هادئ يعيد الدورة من البداية.</p></div></div><a class="motion" href="motion-preview.html">افتح معاينة الحركة</a><p>الملف الحركي 1080×1920 ودورته 8 ثوانٍ. طبقات الشعار معنونة داخل SVG؛ يمكن إعادة بناء الحركة في After Effects أو استيرادها إلى أدوات الويب. يفضّل إبقاء النصوص العربية خارج التوليد الصوري.</p><p>التسليم: SVG للنصوص والأشكال القابلة للتحرير، PNG للمعاينة والنشر، JSON لإعادة البناء البرمجي، HTML للمعاينة والتوثيق، والخط الأصلي. احتفظ بنسخة من النص القابل للتعديل قبل تحويله إلى مسارات في برنامج التصميم.</p><p class="note">رسمة ورقة الاقتراع تستخدم الأحرف «ع م» التي حددها صاحب المشروع. هي عنصر تصميمي، وليست تحققاً من ورقة اقتراع حالية أو معلومات انتخابية رسمية.</p></section>
<section class="sources"><div class="eyebrow">05 / المراجع والمصادر</div><h2>مرجع واضح لكل عنصر.</h2><p>الأخضر من مرجع الهوية المرفق؛ الاستدارة من المرجع الأزرق. استلهام الحجم التحريري من <a href="https://www.behance.net/gallery/220671707/The-Breakdown-2020-Election-coverage">The Breakdown</a>، والتناوب بين التعبئة والحدود من <a href="https://www.canva.com/templates/EAEJDd_l2cM-blue-and-orange-campaign-posters/">قالب Canva المرجعي</a>. التكوينات هنا أصلية وليست نسخاً من تلك الأعمال.</p><p>رمز القائمة داخل العلم مصدره <a href="https://commons.wikimedia.org/wiki/File:Raam_logo_2021.svg">Raam logo 2021</a>. هذه نسخة معنونة 2021؛ لم يُفترض أنها أحدث شعار رسمي.</p><p>صورة منصور عباس: <a href="https://commons.wikimedia.org/wiki/File:Mansour_Abbas_(R_H_4290).jpg">Ronen Horesh / Knesset Archives</a>، 15 نوفمبر 2022، <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a>. قُصّت داخل القالب فقط. الصورة المعدّلة تخضع للرخصة نفسها. الإسناد لا يعني تأييد المصور أو الأرشيف للمجموعة.</p><p>الاقتباس من <a href="https://m.knesset.gov.il/AR/News/PressReleases/Pages/press19012026_3.aspx">أخبار الكنيست، 19 يناير 2026</a> في سياق جلسة حول العنف والجريمة. نُقل كنص منسوب إلى قائله، وليس خبراً جديداً أو تقريراً مستقلاً. رابط التحقق وتفاصيل الترخيص محفوظة في assets/source/source-provenance.json.</p><p>الخط: <a href="https://github.com/google/fonts/tree/main/ofl/cairo">Cairo / Google Fonts</a>، رخصة SIL Open Font License. ملفات الخط والرخصة في assets/fonts.</p><p>استُخدم Qwen محلياً لتحليل المراجع وAider لكتابة محرك SVG. الشعار النهائي إعادة رسم هندسية قابلة للتحرير. مقارنة توليد الصور في ComfyUI منفصلة عن هذه الأصول التنفيذية؛ تزويد النماذج بالمراجع لا يعني تدريبها أو ضبطها الدقيق.</p></section></main><footer>أولتراس الموحدة — نظام بصري قابل للتطوير / نسخة مراجعة 0.1</footer></html>'''
    guide = guide.replace('FONT',fontcss).replace('LOGO',logo).replace('SWATCHES',swatches).replace('CARDS',cards)
    (OUT/'brand-guide.html').write_text(guide,encoding='utf-8')
    motion = '''<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><title>أولتراس الموحدة — الحركة</title><style>FONT
*{box-sizing:border-box}html,body{margin:0;width:1080px;height:1920px;overflow:hidden;background:#006838;font-family:Cairo,Arial,sans-serif}.scene{position:relative;width:1080px;height:1920px;color:#F7F8EF}.small{position:absolute;top:90px;right:84px;font-size:33px;font-weight:850}.disc{position:absolute;top:255px;left:200px;width:680px;height:680px;border-radius:50%;background:#B5F36B;animation:disc 8s ease-in-out infinite}.logo{position:absolute;top:233px;left:144px;width:792px;height:614px;animation:logo 8s cubic-bezier(.2,.8,.2,1) infinite}.logo svg{width:100%;height:100%;overflow:visible}.logo svg>text{display:none}.logo #flag{transform-box:fill-box;transform-origin:left bottom;animation:flag 8s ease-in-out infinite}.title{position:absolute;right:90px;top:940px;font-size:143px;font-weight:950;line-height:1.43;animation:title 8s ease-in-out infinite}.title .line2{display:block;color:transparent;paint-order:stroke fill;-webkit-text-stroke:5.5px #F7F8EF;animation:fill 8s ease-in-out infinite}.lower{position:absolute;right:80px;left:80px;top:1475px;background:#F7F8EF;color:#006838;border-radius:38px;padding:38px 46px;animation:lower 8s ease-in-out infinite}.lower b{font-size:48px;display:block}.lower span{font-size:29px}.foot{position:absolute;right:90px;bottom:110px;font-size:25px;color:#B5F36B}@keyframes disc{0%{transform:scale(.8);opacity:0}14%,86%{transform:scale(1);opacity:1}100%{transform:scale(1.08);opacity:0}}@keyframes logo{0%,3%{transform:translateY(65px);opacity:0}22%,85%{transform:translateY(0);opacity:1}100%{transform:translateY(-25px);opacity:0}}@keyframes flag{0%,18%,80%,100%{transform:skewY(0)}38%{transform:skewY(-3deg)}58%{transform:skewY(2deg)}}@keyframes title{0%,20%{transform:translateY(55px);opacity:0}36%,84%{transform:translateY(0);opacity:1}100%{transform:translateY(-30px);opacity:0}}@keyframes fill{0%,35%{color:transparent}52%,87%{color:#F7F8EF}100%{color:transparent}}@keyframes lower{0%,54%{transform:translateY(45px);opacity:0}67%,86%{transform:translateY(0);opacity:1}100%{transform:translateY(-20px);opacity:0}}@media(prefers-reduced-motion:reduce){*{animation:none!important}.title .line2{color:#F7F8EF}}
</style><main class="scene"><div class="small">أولتراس الموحدة</div><div class="disc"></div><div class="logo">LOGO</div><div class="title">أولتراس<span class="line2">الموحدة</span></div><div class="lower"><b>اسم المتحدث هنا</b><span>الصفة / المناسبة</span></div><div class="foot">مجموعة مناصرين مستقلة</div></main></html>'''
    motion_logo = logo.replace('viewBox="0 0 1200 930"', 'viewBox="250 50 700 600"')
    motion = motion.replace('color:transparent;', 'color:#006838;').replace('color:transparent}', 'color:#006838}')
    (OUT/'motion-preview.html').write_text(motion.replace('FONT',fontcss).replace('LOGO',motion_logo),encoding='utf-8')

def render():
    runner = OUT/'render-proof.cjs'
    code = r'''const {chromium}=require(PW);const fs=require('fs');const path=require('path');
(async()=>{const b=await chromium.launch({headless:true,executablePath:CHROME,args:['--disable-gpu','--no-sandbox']});
const spec=JSON.parse(fs.readFileSync(SPEC,'utf8'));const report=[];
for(const a of spec.assets){const p=await b.newPage({viewport:{width:a.width,height:a.height},deviceScaleFactor:1});
const svg=fs.readFileSync(path.join(OUT,a.id+'.svg'),'utf8');await p.setContent('<html><style>html,body{margin:0;line-height:0;background:transparent}svg{display:block}</style><body>'+svg+'</body></html>');await p.evaluate(()=>document.fonts.ready);
await p.screenshot({path:path.join(OUT,a.id+'.png'),omitBackground:true});
const errors=await p.evaluate(()=>[...document.querySelectorAll('text')].map(t=>({text:t.textContent,box:t.getBBox(),rect:t.getBoundingClientRect().toJSON()})).filter(t=>t.rect.left< -1||t.rect.right>innerWidth+1||t.rect.top< -1||t.rect.bottom>innerHeight+1));
report.push({id:a.id,overflow:errors});await p.close();}
fs.writeFileSync(path.join(OUT,'render-report.json'),JSON.stringify(report,null,2));await b.close();})();'''
    for key,value in [('PW',str(PLAYWRIGHT)),('CHROME',str(CHROME)),('SPEC',str(ROOT/'scripts/identity_spec.json')),('OUT',str(OUT))]:
        code=code.replace(key,json.dumps(value))
    runner.write_text(code,encoding='utf-8')
    subprocess.run([str(NODE),str(runner)],check=True)
    entries = ['logo-primary','01-introduction','02-quote','03-comparison','04-important-news','05-voting']
    sheet = Image.new('RGB',(1800,1780),'#E9EEE5')
    for n,name in enumerate(entries):
        im=Image.open(OUT/(name+'.png')).convert('RGBA')
        back=Image.new('RGBA',im.size,'#F7F8EF');back.alpha_composite(im)
        tile=ImageOps.contain(back.convert('RGB'),(540,760))
        x=30+(n%3)*600+(540-tile.width)//2;y=35+(n//3)*870+(760-tile.height)//2
        sheet.paste(tile,(x,y))
        ImageDraw.Draw(sheet).text((30+(n%3)*600,810+(n//3)*870),name,fill='#073E2A',font_size=23)
    sheet.save(OUT/'identity-overview.jpg',quality=93)
    print('Rendered SVG assets, contact sheet, guide and motion HTML.')

if __name__=='__main__':
    documents()
    render()
